window.listOfSelect=window.listOfSelect||[],window.roroAddOption=function(e,t,o,n=null){let i=listOfSelect.find(t=>t.id==="roro-wrapper-"+e);i&&i.ready.then(()=>{let e=new Option(t,null,o);e.ready.then(()=>{i.addOption(e,n)})})},window.roroDisableSelect=function(e,t=!0){let o=listOfSelect.find(t=>t.id==="roro-wrapper-"+e);o.ready.then(()=>{o.disable(t)})},window.roroReadonlySelect=function(e,t=!0){let o=listOfSelect.find(t=>t.id==="roro-wrapper-"+e);o.ready.then(()=>{o.readonly(t)})},window.roroShowDropDown=function(e,t=!0){let o=listOfSelect.find(t=>t.id==="roro-wrapper-"+e);o.ready.then(()=>{let n=o.elt;if(!o)throw new Error(`Select with id ${e} not found`);n.data("show",t),o.showDropDown(t)})},window.addSelect=function(e){let t=new RoroSelect(e.data("id"),e.data("options"),e.data("value"));listOfSelect.push(t)},window.addMultiSelect=function(e){let t=new RoroMultiSelect(e.data("id"),e.data("name"),e.data("options"),e.data("values"));listOfSelect.push(t)},$(document).ready(function(){$(".roro-wrapper-select").each(function(){addSelect($(this))}),$(".roro-wrapper-multi-select").each(function(){addMultiSelect($(this))})});